func (q *Queries) GroupSignatories(ctx context.Context, arg GroupSignatoriesParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, groupSignatories, arg.GroupID, arg.OfficialsOnly)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

