const setWithdrawalRequestStatus = `-- name: SetWithdrawalRequestStatus :exec
UPDATE withdrawal_requests SET
    status         = $1::withdrawal_request_status,
    decided_at     = CASE WHEN $1::withdrawal_request_status IN ('approved', 'declined', 'cancelled')
                          THEN now() ELSE decided_at END,
    decline_reason = coalesce($2, decline_reason),
    updated_at     = now()
WHERE group_id = $3 AND id = $4
`

type SetWithdrawalRequestStatusParams struct {
	Status        WithdrawalRequestStatus
	DeclineReason *string
	GroupID       int64
	ID            int64
}

func (q *Queries) SetWithdrawalRequestStatus(ctx context.Context, arg SetWithdrawalRequestStatusParams) error {
	_, err := q.db.Exec(ctx, setWithdrawalRequestStatus,
		arg.Status,
		arg.DeclineReason,
		arg.GroupID,
		arg.ID,
	)
	return err
}

